    ('ATLETICO DEC', 'CHARLIE LAKIN::BARNET', '2026-09-03', null),
    ('ATLETICO DEC', 'ARIBIM PEPPLE::PLYMOUTH', '2026-08-01', null),
    ('ATLETICO DEC', 'JEAN-PHILIPPE MATETA::CRYSTAL PALACE', '2026-08-01', '2026-09-03'),
