    ('ATLETICO DEC', 'DANE SCARLETT::LEYTON ORIENT', '2026-09-03', '2026-10-08'),
    ('ATLETICO DEC', 'VIKTOR GYOKERES::ARSENAL', '2026-10-08', null),
    ('ATLETICO DEC', 'TROY PARROTT::AZ ALKMAAR', '2026-08-01', '2026-08-20'),
