    ('ATLETICO DEC', 'BRIAN BROBBEY::SUNDERLAND', '2026-08-01', null)
  ) as v(team_name, player_key, acquired_on, released_on)
),
memberships_ins as (
  insert into public.squad_memberships (season_id, team_id, player_id, acquired_at, released_at)
  select s.id,
         t.id,
         pm.player_id,
         (mr.acquired_on::date)::timestamptz,
         case when mr.released_on is null then null
              else ((mr.released_on::date + 1)::timestamp - interval '1 second') at time zone 'utc'
         end
  from season_ins s
  join membership_rows mr on true
  join teams_ins t on t.name = mr.team_name
  join player_map pm on pm.player_key = mr.player_key
  returning id
)
select
  (select count(*) from season_ins) as seasons,
  (select count(*) from teams_ins) as teams,
  (select count(*) from players_ins) as players,
  (select count(*) from memberships_ins) as memberships;

